CELL['macronutrients-protein']=dict(lead='Every cell builds its own proteins from amino acids. Here is where each step happens, in a typical cell.',aria='Marble drawing of a typical cell with numbered parts: nucleus, ribosomes, rough ER, Golgi, cytosol, mitochondria, cytoskeleton, cell membrane and lysosomes.',
 sites=[('nucleus', 'Nucleus', 'DNA holds the gene for every protein. It is wound on spools of histone proteins, and a gene is copied into messenger RNA (mRNA) to send out.', ['nucleus'], ['nucleus']),
 ('ribo', 'Ribosomes', 'Read the mRNA and join amino acids one by one with peptide bonds. Free ribosomes make the proteins that stay in the cytosol.', ['ribo'], ['ribo']),
 ('rer', 'Rough ER', 'Ribosomes on it make proteins for export or for membranes. Inside, the chain folds and S–S links form.', ['rer'], ['rer']),
 ('golgi', 'Golgi', 'Adds sugar tags, sorts the finished proteins and ships them in little sacs to the membrane or out of the cell, like albumin from liver cells.', ['golgi'], ['golgi']),
 ('cytosol', 'Cytosol', 'The fluid inside the cell, crowded with enzyme proteins that run its reactions, such as breaking glucose down for energy.', ['cytosol'], ['cytosol']),
 ('mito', 'Mitochondria', 'Their enzymes burn fuel and their protein machines make ATP. The carbon from spare amino acids is burned here too.', ['mito'], ['mito']),
 ('cyto', 'Cytoskeleton', 'Protein fibers that give the cell its shape and move things around inside it. In muscle cells, actin and myosin slide past each other to contract.', ['cyto'], ['cyto']),
 ('membrane', 'Cell membrane', 'Channel and carrier proteins let amino acids, glucose and salts in and out; receptor proteins catch signals such as insulin.', ['membrane'], ['membrane']),
 ('lyso', 'Lysosomes', 'Small sacs of enzymes that break worn-out proteins and cell parts back down to amino acids for reuse.', ['lyso'], ['lyso'])],
 seg={'name': 'Inside a Cell',
 'text': 'Zoom in to a single cell and protein is everywhere. The recipe sits in the nucleus as DNA. A copy, called messenger RNA, travels out to the ribosomes, which link amino acids into a chain. '
         "Proteins headed out of the cell are made on the rough ER, then finished and shipped by the Golgi. Inside, enzyme proteins run the cell's chemistry, protein fibers hold its shape, and "
         'membrane proteins act as doors and doorbells. Worn-out proteins go to the lysosomes, which break them back into amino acids to use again.',
 'part': 'cell-uses',
 'cue': 'The cell drawing and its numbered parts',
 'foodBody': [{'name': 'Histones', 'text': 'Not something you eat as such: every cell makes its own histone proteins, rich in the amino acids lysine and arginine, to package its DNA.'},
              {'name': 'Amino acids', 'text': 'From the protein you eat, digested and carried in the blood; cells also make the 11 non-essential ones themselves.'},
              {'name': 'Enzymes', 'text': 'Enzymes in food are digested like any protein; your cells build their own from amino acids.'},
              {'name': 'Insulin receptor', 'text': 'A protein in the membrane of muscle, fat and liver cells. When insulin binds it, the cell takes up glucose.'}]})
